// Normalisation et enrichissement du ticket entrant
const body = $input.first().json.body || $input.first().json;

const ticket = {
  id: `TKT-${Date.now()}`,
  timestamp: new Date().toISOString(),
  source: body.source || 'web',
  utilisateur: {
    nom: body.nom || body.name || 'Inconnu',
    email: body.email || '',
    departement: body.departement || body.department || 'Non précisé'
  },
  sujet: body.sujet || body.subject || body.titre || '',
  description: body.description || body.message || body.contenu || '',
  urgence_declaree: body.urgence || body.priority || 'normal',
  tags: body.tags || []
};

// Validation minimale
if (!ticket.sujet && !ticket.description) {
  throw new Error('Ticket invalide : sujet ou description requis');
}

return [{ json: ticket }];

const ticket = $('🔧 Normalisation Ticket').first().json;
const aiRaw = $input.first().json.output?.[0]?.content?.[0]?.text || $input.first().json.text || $input.first().json.message?.content || $input.first().json.choices?.[0]?.message?.content || '';

let diagnostic;
try {
  // Nettoyer les backticks si présents
  const cleaned = aiRaw.replace(/```json|```/g, '').trim();
  diagnostic = JSON.parse(cleaned);
} catch(e) {
  // Fallback si parsing échoue
  diagnostic = {
    categorie: 'autre',
    criticite: 'P3',
    score_confiance: 0.5,
    resolution_automatique_possible: false,
    reponse_utilisateur: 'Votre ticket a été reçu et est en cours d\'analyse par notre équipe.',
    instructions_technicien: 'Analyser manuellement. Parsing IA échoué.',
    mots_cles: [],
    temps_resolution_estime: '4h',
    equipe_recommandee: 'Management',
    justification: 'Fallback — réponse IA non parsable'
  };
}

// Désanonymisation — restaure les vraies valeurs (nom, email, tel...) dans le texte
// généré par l'IA, qui n'a vu que des jetons [TYPE_N]. Même logique que le nœud
// "Restaurer valeurs réelles" de PII_Guard_Anonymisation, appliquée ici pour couvrir
// les 3 champs texte de la réponse IA en un seul passage.
const mappingPii = ($('🔒 Anonymiser Ticket').first().json || {}).mapping_pii || {};
function desanonymiser(texte) {
  if (!texte || typeof texte !== 'string') return texte;
  let resultat = texte;
  for (const [token, valeurReelle] of Object.entries(mappingPii)) {
    const tokenEchappe = token.replace(/[[\]]/g, '\\$&');
    resultat = resultat.replace(new RegExp(tokenEchappe, 'g'), valeurReelle);
  }
  return resultat;
}
diagnostic.reponse_utilisateur = desanonymiser(diagnostic.reponse_utilisateur);
diagnostic.instructions_technicien = desanonymiser(diagnostic.instructions_technicien);
diagnostic.justification = desanonymiser(diagnostic.justification);

// SLA calculé une seule fois ici (source unique de vérité, réutilisée par les nœuds suivants)
const slaOffsetsHeures = { P1: 1, P2: 4, P3: 8, P4: 24 };
const heuresSla = slaOffsetsHeures[diagnostic.criticite] || 8;
const slaDeadline = new Date();
slaDeadline.setHours(slaDeadline.getHours() + heuresSla);

// Enrichissement final
const result = {
  ...ticket,
  diagnostic: {
    ...diagnostic,
    traite_le: new Date().toISOString(),
    sla_deadline: slaDeadline.toISOString(),
    sla_target_minutes: heuresSla * 60
  },
  routing: {
    auto_resolvable: diagnostic.score_confiance >= 0.85 && diagnostic.resolution_automatique_possible,
    escalade_requise: diagnostic.score_confiance < 0.85 || !diagnostic.resolution_automatique_possible
  }
};

return [{ json: result }];

// Calcul SLA et log pour le dashboard (trace d'exécution — la persistance réelle
// est faite côté Supabase par l'Edge Function it-support-demo-ticket qui appelle ce webhook)
const data = $('⚙️ Parse & Enrich Diagnostic').first().json;
const isAuto = data.routing.auto_resolvable;

const heures = Math.round(data.diagnostic.sla_target_minutes / 60) || 8;

// Temps de triage réel mesuré (réception webhook -> diagnostic IA parsé), plus fiable
// qu'une valeur aléatoire pour un pitch qui promet un ROI mesurable.
const triageMs = new Date(data.diagnostic.traite_le).getTime() - new Date(data.timestamp).getTime();
const triageSecondes = Math.max(0, Math.round(triageMs / 1000));

const log = {
  ticket_id: data.id,
  timestamp: new Date().toISOString(),
  utilisateur: data.utilisateur,
  sujet: data.sujet,
  source: data.source,
  diagnostic: {
    categorie: data.diagnostic.categorie,
    criticite: data.diagnostic.criticite,
    score_confiance: data.diagnostic.score_confiance,
    equipe: data.diagnostic.equipe_recommandee,
    temps_estime: data.diagnostic.temps_resolution_estime
  },
  traitement: {
    mode: isAuto ? 'AUTOMATIQUE' : 'ESCALADE_HUMAINE',
    sla_heures: heures,
    sla_deadline: data.diagnostic.sla_deadline,
    sla_status: 'EN_COURS'
  },
  kpis: {
    temps_triage_secondes: triageSecondes,
    resolution_auto: isAuto
  }
};

console.log('TICKET_LOG:', JSON.stringify(log));
return [{ json: log }];

