const diag = $('⚙️ Parse & Enrich Diagnostic').first().json;
const isAuto = diag.routing.auto_resolvable;

return [{
  json: {
    status: 'ok',
    ticket_id: diag.id,
    mode_traitement: isAuto ? 'AUTOMATIQUE' : 'ESCALADE_HUMAINE',
    decision: isAuto ? 'auto_resolved' : 'escalated',
    criticite: diag.diagnostic.criticite,
    categorie: diag.diagnostic.categorie,
    category: diag.diagnostic.categorie,
    confidence: diag.diagnostic.score_confiance,
    response_text: diag.diagnostic.reponse_utilisateur,
    escalated_to: isAuto ? '' : diag.diagnostic.equipe_recommandee,
    equipe: diag.diagnostic.equipe_recommandee,
    sla_deadline: diag.diagnostic.sla_deadline,
    sla_target_minutes: diag.diagnostic.sla_target_minutes,
    message: 'Ticket enregistré et traité avec succès'
  }
}];
